func test_dialect_TestDialect_test_heredoc_strings(self *Case, a Args) Value {
	var dialect Value
	_ = []Value{dialect}
	for _, item_ := range Iter(NewTuple("clickhouse", "postgres", "redshift")) {
		dialect = item_
		self.Do(614, func() {
			self.AssertRaises(func(cm_ Value) {
				_ = cm_
				Stmt(Call(G("sqlglot.parse_one"), "SELECT $tag1$invalid heredoc string$tag2$", Kw("dialect", dialect)))
			}, G("sqlglot.TokenError"))
		})
		self.Do(618, func() {
			self.AssertRaises(func(cm_ Value) {
				_ = cm_
				Stmt(Call(G("sqlglot.parse_one"), "SELECT $tag1$invalid heredoc string", Kw("dialect", dialect)))
			}, G("sqlglot.TokenError"))
		})
		self.Do(622, func() {
			self.ValidateAll("SELECT 'this is a heredoc string'", Kw("read", NewDict(dialect, "SELECT $$this is a heredoc string$$")))
		})
		self.Do(628, func() { self.ValidateAll("SELECT ''", Kw("read", NewDict(dialect, "SELECT $$$$"))) })
		self.Do(636, func() {
			self.ValidateAll("SELECT 'this is also a heredoc string'", Kw("read", NewDict(dialect, "SELECT $foo$this is also a heredoc string$foo$")))
		})
		self.Do(642, func() { self.ValidateAll("SELECT ''", Kw("read", NewDict(dialect, "SELECT $foo$$foo$"))) })
	}
	return nil
}

