		self.SubTest(func() {
			self.Do(4718, func() {
				self.ValidateAll(F("SELECT col NOT LIKE ", FV{V: quantifier}, " (x, y, z)"), Kw("write", NewDict("", F("SELECT col NOT LIKE ", FV{V: quantifier}, " (x, y, z)"), "duckdb", F("SELECT (col NOT LIKE x ", FV{V: connector}, " col NOT LIKE y) ", FV{V: connector}, " col NOT LIKE z"))))
			})
		}, F("Testing NOT LIKE ", FV{V: quantifier}))
